    int maxX, maxY;
    if (scanf("%d %d", &maxX, &maxY) != 2) return 0;
    memset(scents, 0, sizeof(scents));
    int x, y;
    char dir;
    char cmd[150];
    while (scanf("%d %d %c", &x, &y, &dir) == 3) {
        scanf("%s", cmd);
        int d = get_dir(dir);
        int lost = 0;
        int len = strlen(cmd);
