                carry = 1;
                carries++;
            } else {
                carry = 0;
            }
            a /= 10;
            b /= 10;
        }
        if (carries == 0)
            printf("No carry operation.\n");
        else if (carries == 1)
            printf("1 carry operation.\n");
        else
            printf("%d carry operations.\n", carries);
    }
