typedef struct {
    int ascii;
    int freq;
} CharFreq;

int cmp(const void *a, const void *b) {
    CharFreq *ca = (CharFreq *)a;
    CharFreq *cb = (CharFreq *)b;
    if (ca->freq != cb->freq) {
        return ca->freq - cb->freq;
    }
    return cb->ascii - ca->ascii;
}

int main() {
    char line[1005];
