        for (int i = 32; i < 128; i++) {
            if (counts[i] > 0) {
                items[k].ascii = i;
                items[k].freq = counts[i];
                k++;
            }
        }
        qsort(items, k, sizeof(CharFreq), cmp);
        if (!first) printf("\n");
        first = 0;
        for (int i = 0; i < k; i++) {
            printf("%d %d\n", items[i].ascii, items[i].freq);
