#include <stdio.h>
#include <stdlib.h>

int M;

int is_odd(int x) {
    return (x % 2 != 0);
}

int cmp(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    int mod_x = x % M;
    int mod_y = y % M;

    if (mod_x != mod_y)
        return mod_x - mod_y;

    int odd_x = is_odd(x);
    int odd_y = is_odd(y);

    if (odd_x != odd_y) {
        return odd_y - odd_x; // 奇數在前 (odd=1 排在 odd=0 前面)
    }

    if (odd_x) {
        return y - x; // 兩奇數：大者在前 (降冪)
    } else {
        return x - y; // 兩偶數：小者在前 (升冪)
    }
}

int main() {
    int n;
    while (scanf("%d %d", &n, &M) == 2) {
        printf("%d %d\n", n, M);
        if (n == 0 && M == 0) break;
        int arr[10005];
        for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
        qsort(arr, n, sizeof(int), cmp);
        for (int i = 0; i < n; i++) printf("%d\n", arr[i]);
    }
    return 0;
}

